"""Render a table of contents as a nested Markdown list."""

from __future__ import annotations

import re


def slug(title: str) -> str:
    """GitHub-style anchor: lowercase, punctuation dropped, spaces to hyphens."""
    return title.strip().lower().replace(" ", "-")


def render_toc(headings: list[tuple[int, str]]) -> str:
    """One '- [Title](#slug)' line per heading, indented two spaces per level."""
    if not headings:
        return ""
    top = min(level for level, _ in headings)
    lines = [f"{'  ' * (level - top)}- [{title}](#{slug(title)})" for level, title in headings]
    return "\n".join(lines) + "\n"

