from mdtoc.render import render_toc, slug


def test_slug_simple():
    assert slug("Getting Started") == "getting-started"


def test_slug_punctuation():
    assert slug("Hello, World!") == "hello-world"


def test_render_nested():
    toc = render_toc([(1, "Intro"), (2, "Install"), (1, "Usage")])
    assert toc == "- [Intro](#intro)\n  - [Install](#install)\n- [Usage](#usage)\n"

